import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Dashboard from './pages/Dashboard';
import Plans from './pages/Plans';
import About from './pages/About';
import Login from './pages/Login';
import Signup from './pages/Signup';
import Profile from './pages/Profile';
import Claims from './pages/Claims';

export default function App() {
  const [activeTab, setActiveTab] = useState('home');
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);

  // Restore user session on load
  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    const savedToken = localStorage.getItem('token');
    if (savedUser && savedToken) {
      setUser(JSON.parse(savedUser));
      setToken(savedToken);
    }
  }, []);

  const setAuth = (userData, userToken) => {
    setUser(userData);
    setToken(userToken);
    localStorage.setItem('user', JSON.stringify(userData));
    localStorage.setItem('token', userToken);
  };

  const logout = () => {
    setUser(null);
    setToken(null);
    localStorage.removeItem('user');
    localStorage.removeItem('token');
    setActiveTab('login');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'home':
        return <Home setActiveTab={setActiveTab} />;
      case 'dashboard':
        return <Dashboard />;
      case 'plans':
        return <Plans />;
      case 'about':
        return <About />;
      case 'claims':
        return <Claims />;
      case 'login':
        return <Login setAuth={setAuth} setActiveTab={setActiveTab} />;
      case 'signup':
        return <Signup setAuth={setAuth} setActiveTab={setActiveTab} />;
      case 'profile':
        return <Profile user={user} token={token} logout={logout} setUser={setUser} />;
      default:
        return <Home setActiveTab={setActiveTab} />;
    }
  };

  return (
    <div className="min-h-screen bg-base flex flex-col selection:bg-primary/30 selection:text-primary text-content">
      <Navbar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        user={user} 
      />

      <main className={`flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full ${activeTab === 'home' ? 'pt-0 pb-10' : 'py-10'}`}>
        {renderContent()}
      </main>

      <Footer />
    </div>
  );
}

import React from 'react';

const Card = ({ children, className = "", hover = true, interactive = false }) => {
  return (
    <div className={`
      relative rounded-3xl p-6 sm:p-8 bg-surface/90 backdrop-blur-xl
      border border-border shadow-xl
      transition-all duration-300 ease-out
      ${hover ? 'hover:border-border-hover hover:-translate-y-1 hover:shadow-2xl' : ''}
      ${className}
    `}>
      {children}
    </div>
