export default Card;

import React, { useState } from 'react';

export default function Login({ setAuth, setActiveTab }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const response = await fetch('http://localhost:5000/api/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email, password }),
      });

      const data = await response.json();

      if (response.ok) {
        setAuth(data, data.token);
        setActiveTab('dashboard');
      } else {
        setError(data.message || 'Login failed');
      }
    } catch (err) {
      setError('Cannot connect to server');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-[calc(100vh-12rem)] flex flex-col items-center justify-center animate-fadeIn w-full">
      <div className="w-full max-w-md md:max-w-lg bg-surface/80 backdrop-blur-xl border border-border p-8 sm:p-10 rounded-3xl shadow-2xl shadow-black/50 mx-auto">
        <div className="text-center mb-8">
          <h2 className="text-3xl font-extrabold text-content mb-2 tracking-tight">Welcome Back</h2>
          <p className="text-content-secondary font-medium">Sign in to GigGuard to manage your protection.</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/20 text-red-500 rounded-xl text-sm font-semibold">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-bold text-content-secondary mb-2">Email Address</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="w-full bg-base/50 border border-border-hover rounded-xl px-4 py-3.5 text-content placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary transition-all font-medium shadow-sm"
              placeholder="you@example.com"
            />
          </div>

          <div>
            <label className="block text-sm font-bold text-content-secondary mb-2">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="w-full bg-base/50 border border-border-hover rounded-xl px-4 py-3.5 text-content placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary transition-all font-medium shadow-sm"
              placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-primary hover:bg-primary-hover text-content font-bold py-3.5 px-4 rounded-xl border border-primary/30 shadow-md hover:shadow-lg hover:-translate-y-0.5 active:scale-95 transition-all duration-300 flex justify-center items-center mt-2"
          >
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>

        <p className="mt-8 text-center text-content-secondary text-sm font-medium">
          Don't have an account?{' '}
          <button onClick={() => setActiveTab('signup')} className="text-primary hover:text-primary font-bold hover:underline transition-all">
            Sign up
          </button>
        </p>
      </div>
    </div>
  );
}

import React, { useEffect, useState, useRef } from 'react';
import { User, Shield, Key, Building2, Phone, MapPin, Briefcase, Edit2, Save, X, Camera } from 'lucide-react';

export default function Profile({ user, token, logout, setUser }) {
  const [profileData, setProfileData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({});
  const [saving, setSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef(null);

  useEffect(() => {
    fetchProfile();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  const fetchProfile = async () => {
    try {
      const response = await fetch('http://localhost:5000/api/profile', {
        headers: {
          Authorization: `Bearer ${token}`
        }
      });

      if (response.ok) {
        const data = await response.json();
        setProfileData(data);
        if (setUser) {
          const updatedGlobalUser = { ...user, name: data.name, profilePic: data.profilePic };
          setUser(updatedGlobalUser);
          localStorage.setItem('user', JSON.stringify(updatedGlobalUser));
        }

        setFormData({
          name: data.name || '',
          company: data.company || '',
          phone: data.phone || '',
          experience: data.experience || '',
          street: data.address?.street || '',
          landmark: data.address?.landmark || '',
          pincode: data.address?.pincode || '',
          profilePic: data.profilePic || ''
        });
      } else {
        setError('Failed to load profile. Please login again.');
        logout();
      }
    } catch (err) {
      setError('Connection error.');
    } finally {
      setLoading(false);
    }
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setIsUploading(true);
    const uploadData = new FormData();
    uploadData.append('profilePic', file);

    try {
      const res = await fetch('http://localhost:5000/api/upload', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`
        },
        body: uploadData
      });

      if (res.ok) {
        const data = await res.json();
        setFormData(prev => ({ ...prev, profilePic: data.imageUrl }));
        setProfileData(prev => ({ ...prev, profilePic: data.imageUrl }));
      } else {
        setError('Image upload failed.');
      }
    } catch (err) {
      setError('Server connection error during upload.');
    } finally {
      setIsUploading(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setError('');

    try {
      const payload = {
        name: formData.name,
        company: formData.company,
        phone: formData.phone,
        experience: formData.experience,
        profilePic: formData.profilePic,
        address: {
          street: formData.street,
          landmark: formData.landmark,
          pincode: formData.pincode
        }
      };

      const response = await fetch('http://localhost:5000/api/profile', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });

      if (response.ok) {
        const updatedData = await response.json();
        setProfileData(updatedData);
        setIsEditing(false);

        if (setUser) {
          const globalUserUpdate = { ...user, name: updatedData.name, profilePic: updatedData.profilePic };
          setUser(globalUserUpdate);
          localStorage.setItem('user', JSON.stringify(globalUserUpdate));
        }

      } else {
        const data = await response.json();
        setError(data.message || 'Failed to update profile');
      }
    } catch (err) {
      setError('Connection error while saving');
    } finally {
      setSaving(false);
    }
  };

  const handleCancel = () => {
    setFormData({
      name: profileData.name || '',
      company: profileData.company || '',
      phone: profileData.phone || '',
      experience: profileData.experience || '',
      street: profileData.address?.street || '',
      landmark: profileData.address?.landmark || '',
      pincode: profileData.address?.pincode || '',
      profilePic: profileData.profilePic || ''
    });
    setIsEditing(false);
    setError('');
  };

  if (loading) {
    return (
        <div className="flex justify-center items-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-indigo-500"></div>
        </div>
    );
  }

  if (error && !profileData) {
    return (
        <div className="text-center py-20 text-red-500 px-4 bg-surface border border-border rounded-xl shadow-xl">
            <h2 className="text-2xl font-extrabold mb-2">Notice</h2>
            <p className="font-medium text-content-secondary">{error || "You must be logged in to view this page."}</p>
        </div>
    );
  }

  const profileImageUrl = formData.profilePic 
    ? `http://localhost:5000${formData.profilePic}` 
    : (profileData.profilePic ? `http://localhost:5000${profileData.profilePic}` : null);

  return (
    <div className="max-w-4xl mx-auto space-y-6 animate-fadeIn">
      <div className="bg-surface border border-border rounded-2xl p-8 shadow-xl flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center space-x-6">
          <div className="relative group w-24 h-24">
             {profileImageUrl ? (
                <img 
                  src={profileImageUrl} 
                  alt="Profile" 
                  className="w-24 h-24 rounded-full object-cover shadow-lg border-2 border-border-hover group-hover:border-primary transition-colors"
                />
             ) : (
                <div className="w-24 h-24 bg-surface text-content rounded-full flex items-center justify-center shadow-lg border-2 border-border-hover">
                   <span className="text-4xl font-extrabold text-content">
                     {profileData.name.charAt(0).toUpperCase()}
                   </span>
                </div>
             )}

             {isEditing && (
                 <div className="absolute inset-0 bg-base/70 backdrop-blur-[2px] rounded-full flex flex-col items-center justify-center text-content opacity-0 group-hover:opacity-100 transition-opacity overflow-hidden border border-primary/50 cursor-pointer">
                   {isUploading ? (
                     <div className="animate-spin rounded-full h-6 w-6 border-2 border-t-2 border-white"></div>
                   ) : (
                   <>
                     <Camera className="w-6 h-6 mb-1 text-content" />
                     <span className="text-xs font-bold text-content">Upload</span>
                     <input 
                       type="file" 
                       onClick={(e) => { e.target.value = null }}
                       className="opacity-0 absolute inset-0 w-full h-full cursor-pointer" 
                       accept="image/*" 
                       onChange={handleImageUpload} 
                     />
                   </>
                   )}
                 </div>
             )}
          </div>
          <div>
            <h1 className="text-3xl font-extrabold text-content mb-1 tracking-tight">{profileData.name}</h1>
            <p className="text-content-secondary font-medium">{profileData.email}</p>
            <div className="mt-3 inline-flex items-center space-x-1.5 px-3 py-1 rounded-full bg-success/10 text-success text-sm font-bold border border-success/20 shadow-sm">
                <Shield className="w-4 h-4" />
                <span>Verified Account</span>
            </div>
          </div>
        </div>

        <div>
          {!isEditing ? (
            <button 
              onClick={() => setIsEditing(true)}
              className="px-6 py-2.5 bg-surface border border-border-hover hover:bg-surface/80 hover:border-slate-600 text-content rounded-xl font-bold transition-all flex items-center shadow-md hover:-translate-y-0.5"
            >
              <Edit2 className="w-4 h-4 mr-2" />
              Edit Profile
            </button>
          ) : (
            <div className="flex gap-3">
              <button 
                onClick={handleCancel}
                disabled={saving}
                className="px-5 py-2.5 bg-surface hover:bg-surface/80 text-content-secondary rounded-xl font-bold transition flex items-center border border-border-hover"
              >
                <X className="w-4 h-4 mr-1" />
                Cancel
              </button>
              <button 
                onClick={handleSave}
                disabled={saving || isUploading}
                className="px-6 py-2.5 bg-primary hover:bg-primary-hover text-content rounded-xl font-bold border border-primary/30 shadow-md hover:shadow-lg hover:-translate-y-0.5 active:scale-95 transition-all duration-300 flex items-center"
              >
                <Save className="w-4 h-4 mr-2" />
                {saving ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          )}
        </div>
      </div>

      {error && isEditing && (
        <div className="p-4 bg-red-500/10 border border-red-500/20 text-red-500 rounded-xl shadow-inner text-sm font-semibold">
          {error}
        </div>
      )}

      {/* Details Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Professional Information */}
        <div className="bg-surface border border-border p-6 md:p-8 rounded-2xl shadow-xl hover:shadow-2xl transition-shadow">
            <h2 className="text-xl font-extrabold text-content mb-6 border-b border-border pb-4 flex items-center">
                <Briefcase className="w-5 h-5 mr-3 text-primary" />
                Professional Details
            </h2>

            <div className="space-y-6">
                <div>
                    <label className="text-sm font-bold text-content-secondary mb-2 block">Full Name</label>
                    {isEditing ? (
                      <input 
                        type="text" 
                        value={formData.name} 
                        onChange={e => setFormData({...formData, name: e.target.value})}
                        className="w-full bg-base border border-border-hover rounded-xl px-4 py-3 text-content focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary font-medium transition"
                      />
                    ) : (
                      <p className="text-slate-100 text-lg font-bold">{profileData.name}</p>
                    )}
                </div>

                <div>
                    <label className="text-sm font-bold text-content-secondary mb-2 block">Working Company</label>
                    {isEditing ? (
                      <input 
                        type="text" 
                        placeholder="e.g. Blinkit, Zomato, Uber"
                        value={formData.company} 
                        onChange={e => setFormData({...formData, company: e.target.value})}
                        className="w-full bg-base border border-border-hover rounded-xl px-4 py-3 text-content focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary font-medium transition"
                      />
                    ) : (
                      <p className="text-slate-100 text-lg font-bold">
                        {profileData.company ? profileData.company : <span className="text-content-muted font-medium italic">Not specified</span>}
                      </p>
                    )}
                </div>

                <div>
                    <label className="text-sm font-bold text-content-secondary mb-2 block">Work Experience</label>
                    {isEditing ? (
                      <textarea 
                        rows="3"
                        placeholder="Describe your work experience..."
                        value={formData.experience} 
                        onChange={e => setFormData({...formData, experience: e.target.value})}
                        className="w-full bg-base border border-border-hover rounded-xl px-4 py-3 text-content focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:border-primary font-medium resize-none transition"
                      />
                    ) : (
                      <p className="text-content-secondary font-medium">
                        {profileData.experience ? profileData.experience : <span className="text-content-muted italic">Not specified</span>}
                      </p>
                    )}
                </div>
            </div>
        </div>

        {/* Contact & Address */}
        <div className="bg-surface border border-border p-6 md:p-8 rounded-2xl shadow-xl hover:shadow-2xl transition-shadow">
            <h2 className="text-xl font-extrabold text-content mb-6 border-b border-border pb-4 flex items-center">
                <MapPin className="w-5 h-5 mr-3 text-primary" />
                Contact & Address
            </h2>

            <div className="space-y-6">
                <div>
                    <label className="text-sm font-bold text-content-secondary mb-2 block">Phone Number</label>
                    {isEditing ? (
                      <input 
                        type="tel" 
                        placeholder="+91 9876543210"
                        value={formData.phone} 
                        onChange={e => setFormData({...formData, phone: e.target.value})}
                        className="w-full bg-base border border-border-hover rounded-xl px-4 py-3 text-content focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary font-medium transition"
                      />
                    ) : (
                      <div className="flex items-center text-slate-100 text-lg font-bold">
                        {profileData.phone ? (
                          <><Phone className="w-5 h-5 mr-2 text-content-muted" /> {profileData.phone}</>
                        ) : (
                          <span className="text-content-muted font-medium italic">Not specified</span>
                        )}
                      </div>
                    )}
                </div>

                <div className="space-y-4">
                    <label className="text-sm font-bold text-content-secondary block">Residential Address</label>

                    {isEditing ? (
                      <>
                        <input 
                          type="text" 
                          placeholder="Street Address / Flat No."
                          value={formData.street} 
                          onChange={e => setFormData({...formData, street: e.target.value})}
                          className="w-full bg-base border border-border-hover rounded-xl px-4 py-3 text-content focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:border-primary font-medium transition mb-4"
                        />
                        <div className="grid grid-cols-2 gap-4">
                          <input 
                            type="text" 
                            placeholder="Landmark"
                            value={formData.landmark} 
                            onChange={e => setFormData({...formData, landmark: e.target.value})}
                            className="w-full bg-base border border-border-hover rounded-xl px-4 py-3 text-content focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary font-medium transition"
                          />
                          <input 
                            type="text" 
                            placeholder="PIN Code"
                            value={formData.pincode} 
                            onChange={e => setFormData({...formData, pincode: e.target.value})}
                            className="w-full bg-base border border-border-hover rounded-xl px-4 py-3 text-content focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary font-medium transition"
                          />
                        </div>
                      </>
                    ) : (
                      <div className="bg-base rounded-xl p-5 border border-border/80 shadow-inner">
                        {profileData.address?.street || profileData.address?.pincode ? (
                          <div className="space-y-1.5 text-content-secondary font-medium">
                            <p className="text-content font-bold">{profileData.address?.street}</p>
                            {profileData.address?.landmark && <p className="text-sm text-content-secondary">Near {profileData.address.landmark}</p>}
                            {profileData.address?.pincode && <p className="text-sm font-bold tracking-wide text-primary mt-2 pt-2 border-t border-border/80 inline-block">PIN: {profileData.address.pincode}</p>}
                          </div>
                        ) : (
                          <p className="text-content-muted italic text-sm font-medium">No address added yet.</p>
                        )}
                      </div>
                    )}
                </div>
            </div>
        </div>

      </div>

      {!isEditing && (
        <div className="bg-surface border border-border p-6 rounded-2xl shadow-xl flex items-center justify-between">
            <div className="flex items-center space-x-4">
                <div className="p-3 bg-red-500/10 rounded-xl border border-red-500/20 text-red-400">
                    <Key className="w-6 h-6" />
                </div>
                <div>
                    <h3 className="text-content font-extrabold tracking-tight">Account Security</h3>
                    <p className="text-content-secondary font-medium text-sm mt-0.5">Secure your account or sign out</p>
                </div>
            </div>
            <button 
                onClick={logout} 
                className="px-6 py-2.5 bg-surface border border-red-500/30 text-red-400 hover:bg-red-500/10 hover:border-red-500/50 font-bold rounded-xl transition-all shadow-sm flex items-center gap-2"
            >
                Sign Out
            </button>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';

export default function Signup({ setAuth, setActiveTab }) {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const response = await fetch('http://localhost:5000/api/signup', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ name, email, password }),
      });

      const data = await response.json();

      if (response.ok) {
        setAuth(data, data.token);
        setActiveTab('dashboard');
      } else {
        setError(data.message || 'Signup failed');
      }
    } catch (err) {
      setError('Cannot connect to server');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-[calc(100vh-12rem)] flex flex-col items-center justify-center animate-fadeIn w-full">
      <div className="w-full max-w-md md:max-w-lg bg-surface/80 backdrop-blur-xl border border-border p-8 sm:p-10 rounded-3xl shadow-2xl shadow-black/50 mx-auto">
        <div className="text-center mb-8">
          <h2 className="text-3xl font-extrabold text-content mb-2 tracking-tight">Create an Account</h2>
          <p className="text-content-secondary font-medium">Join GigGuard and secure your income.</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/20 text-red-500 rounded-xl text-sm font-semibold">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-bold text-content-secondary mb-2">Full Name</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
              className="w-full bg-base/50 border border-border-hover rounded-xl px-4 py-3.5 text-content placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary transition-all font-medium shadow-sm"
              placeholder="John Doe"
            />
          </div>

          <div>
            <label className="block text-sm font-bold text-content-secondary mb-2">Email Address</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="w-full bg-base/50 border border-border-hover rounded-xl px-4 py-3.5 text-content placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary transition-all font-medium shadow-sm"
              placeholder="you@example.com"
            />
          </div>

          <div>
            <label className="block text-sm font-bold text-content-secondary mb-2">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              minLength={6}
              className="w-full bg-base/50 border border-border-hover rounded-xl px-4 py-3.5 text-content placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-primary transition-all font-medium shadow-sm"
              placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-primary hover:bg-primary-hover text-content font-bold py-3.5 px-4 rounded-xl border border-primary/30 shadow-md hover:shadow-lg hover:-translate-y-0.5 active:scale-95 transition-all duration-300 flex justify-center items-center mt-2"
          >
            {loading ? 'Creating account...' : 'Create Account'}
          </button>
        </form>

        <p className="mt-8 text-center text-content-secondary text-sm font-medium">
          Already have an account?{' '}
          <button onClick={() => setActiveTab('login')} className="text-primary hover:text-primary font-bold hover:underline transition-all">
            Sign in
          </button>
        </p>
      </div>
    </div>
  );
}
